@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:vibermate_app/core/api/control_api.dart';
import 'package:vibermate_app/core/api/control_models.dart';
import 'package:vibermate_app/preview/preview_control_api.dart';

void main() {
  test('the app reads the script counts the Runtime sends', () {
    // Generated by internal/activity/script_activity_sample_test.go.
    final activity = ScriptActivity.fromJson(
      jsonDecode(
        File('../../api/samples/script-activity.json').readAsStringSync(),
      ),
      'scriptActivity',
    );
    expect(activity.requests, 41);
    expect(activity.truncated, isFalse);
    final guard = activity.forScript('transform.guard')!;
    expect(guard.blocked, 1);
    expect(guard.failed, 1);
    expect(guard.blockReasons.single.reason, 'destructive-command');
    expect(activity.forScript('transform.mask')!.changed, 1);
    expect(activity.forScript('missing'), isNull);
  });

  test('counts that do not add up are refused', () {
    final sample =
        jsonDecode(
              File('../../api/samples/script-activity.json').readAsStringSync(),
            )
            as Map<String, Object?>;
    final scripts = (sample['scripts'] as List).cast<Map<String, Object?>>();
    scripts.first['changed'] = 5;
    expect(
      () => ScriptActivity.fromJson(sample, 'scriptActivity'),
      throwsA(isA<ControlContractException>()),
    );
  });

  test('the preview answers like a Runtime', () async {
    final api = PreviewControlApi();
    addTearDown(api.close);
    expect(api, isA<ScriptActivityReader>());
    final activity = await (api as ScriptActivityReader).scriptActivity();
    expect(activity.scripts, isNotEmpty);
  });
}
